#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_MAX 1024

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];
    char out[OUT_MAX];
    size_t out_len = 0;

    if (strcmp(mode, "to_camel") == 0) {
        int capitalize_next = 0;
        for (size_t i = 0; input[i] != '\0' && out_len < OUT_MAX - 1; ++i) {
            char c = input[i];
            if (c == '_') {
                capitalize_next = 1;
                continue;
            }
            if (capitalize_next && c >= 'a' && c <= 'z')
                c = (char)(c - ('a' - 'A'));
            capitalize_next = 0;
            out[out_len++] = c;
        }
    } else if (strcmp(mode, "to_snake") == 0) {
        for (size_t i = 0; input[i] != '\0' && out_len < OUT_MAX - 1; ++i) {
            char c = input[i];
            if (c >= 'A' && c <= 'Z') {
                if (out_len > 0) {
                    out[out_len++] = '_';
                    if (out_len >= OUT_MAX - 1) break;
                }
                c = (char)(c + ('a' - 'A'));
            }
            out[out_len++] = c;
        }
    } else {
        puts("INVALID_MODE");
        return 0;
    }

    out[out_len] = '\0';
    puts(out);
    return 0;
}
